import 'package:flutter/material.dart'; import 'dart:math' as math;  void main() {   runApp(const FamilleThompsonApp()); }  // --- 1. TA FAMILLE --- class Membre {   final String nom;   final Color couleur;   final String avatar;   Membre({required this.nom, required this.couleur, required this.avatar}); }  final List<Membre> famille = [   Membre(nom: "Maman", couleur: Colors.white, avatar: "👑"),   Membre(nom: "Papa Marc", couleur: Colors.red, avatar: "🦁"),   Membre(nom: "Zoé", couleur: Colors.yellow, avatar: "☀️"),   Membre(nom: "Ellie", couleur: Colors.pink, avatar: "🦄"),   Membre(nom: "Ivy", couleur: Colors.purple, avatar: "🌸"),   Membre(nom: "Olivia", couleur: Colors.cyan, avatar: "🐬"), ];  class FamilleThompsonApp extends StatelessWidget {   const FamilleThompsonApp({super.key});    @override   Widget build(BuildContext context) {     return MaterialApp(       debugShowCheckedModeBanner: false,       theme: ThemeData.dark(),       home: const EcranFamille(),     );   } }  // --- 2. ÉCRAN 1 : MA GANG --- class EcranFamille extends StatelessWidget {   const EcranFamille({super.key});    @override   Widget build(BuildContext context) {     return Scaffold(       backgroundColor: Colors.black,       appBar: AppBar(         backgroundColor: Colors.black,         title: const Text("La Famille Thompson", style: TextStyle(fontWeight: FontWeight.bold)),         centerTitle: true,       ),       body: ListView.builder(         itemCount: famille.length,         itemBuilder: (context, index) {           final membre = famille[index];           // Fausse distance pour l'exemple, on mettra la vraie GPS après           final distances = [0, 85, 32, 120, 45, 210];           return ListTile(             leading: CircleAvatar(               backgroundColor: membre.couleur,               child: Text(membre.avatar, style: const TextStyle(fontSize: 20)),             ),             title: Text(membre.nom, style: TextStyle(color: membre.couleur, fontWeight: FontWeight.bold, fontSize: 20)),             subtitle: Text("${distances[index]}m", style: const TextStyle(color: Colors.white70)),             trailing: Icon(Icons.arrow_forward_ios, color: membre.couleur),             onTap: () {               Navigator.push(                 context,                 MaterialPageRoute(builder: (_) => EcranFleche(membre: membre, distance: distances[index].toDouble())),               );             },           );         },       ),     );   } }  // --- 3. ÉCRAN 2 : LA GROSSE FLÈCHE XXL --- class EcranFleche extends StatefulWidget {   final Membre membre;   final double distance;   const EcranFleche({super.key, required this.membre, required this.distance});    @override   State<EcranFleche> createState() => _EcranFlecheState(); }  class _EcranFlecheState extends State<EcranFleche> with SingleTickerProviderStateMixin {   late AnimationController _controller;    @override   void initState() {     super.initState();     // Pour l'exemple, la flèche tourne doucement. Après on la branchera sur la vraie boussole.     _controller = AnimationController(vsync: this, duration: const Duration(seconds: 4))..repeat();   }    String get message {     if (widget.distance < 10) return "LÈVE LA TÊTE, ELLE EST LÀ !";     if (widget.distance < 50) return "Tu te rapproches !";     return "Elle est par là, continue";   }    @override   Widget build(BuildContext context) {     return Scaffold(       backgroundColor: Colors.black,       body: SafeArea(         child: Column(           children: [             const SizedBox(height: 20),             Text(widget.membre.nom.toUpperCase(),                 style: TextStyle(color: widget.membre.couleur, fontSize: 32, fontWeight: FontWeight.w900)),             Text(widget.membre.avatar, style: const TextStyle(fontSize: 40)),             const Spacer(),             // LA GROSSE FLÈCHE             AnimatedBuilder(               animation: _controller,               builder: (context, child) {                 return Transform.rotate(                   angle: _controller.value * 2 * math.pi,                   child: Icon(Icons.navigation, size: 260, color: widget.membre.couleur),                 );               },             ),             const Spacer(),             Text("${widget.distance.toInt()}m",                 style: TextStyle(color: widget.membre.couleur, fontSize: 72, fontWeight: FontWeight.w900)),             Text(message, style: const TextStyle(color: Colors.white, fontSize: 18)),             const SizedBox(height: 20),             Padding(               padding: const EdgeInsets.all(16.0),               child: Row(                 children: [                   Expanded(                     child: ElevatedButton(                       style: ElevatedButton.styleFrom(backgroundColor: widget.membre.couleur, padding: const EdgeInsets.all(18)),                       onPressed: () => Navigator.pop(context),                       child: Text("Je l'ai trouvée !", style: TextStyle(color: widget.membre.couleur == Colors.white || widget.membre.couleur == Colors.yellow ? Colors.black : Colors.white, fontWeight: FontWeight.bold)),                     ),                   ),                   const SizedBox(width: 12),                   Expanded(                     child: OutlinedButton(                       style: OutlinedButton.styleFrom(side: BorderSide(color: widget.membre.couleur), padding: const EdgeInsets.all(18)),                       onPressed: () {},                       child: Text("Appeler ${widget.membre.nom}", style: TextStyle(color: widget.membre.couleur)),                     ),                   ),                 ],               ),             ),           ],         ),       ),     );   } }